import java.util.*;

public class AirlineExpertSystem {

    static class Rule {
        String condition;
        String action;

        Rule(String condition, String action) {
            this.condition = condition;
            this.action = action;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        ArrayList<Rule> rules = initializeRules();

        System.out.println("Enter flight status (ontime / delayed / canceled):");
        String flightStatus = sc.nextLine();
        String recommendation = applyRules(flightStatus, rules);

        System.out.println(recommendation);
    }

